import heapq
from typing import List


def compute_number_of_locations(N: int, M: int, L: int,
                                g: List[int], roads: List[List[int]]) -> int:
    """roads[j] = [u, v, d]。统计能从 1 出发、到达后还能回家的地点数（含 1 号点）。"""
    adj = [[] for _ in range(N + 1)]
    for u, v, d in roads:
        adj[u].append((v, d))
        adj[v].append((u, d))
    INF = float("inf")
    dist = [INF] * (N + 1)
    near = [0] * (N + 1)  # 最近加油站
    pq = []
    for i in range(1, N + 1):
        if g[i - 1]:
            dist[i], near[i] = 0, i
            pq.append((0, i))
    heapq.heapify(pq)
    while pq:  # 多源 Dijkstra
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v], near[v] = d + w, near[u]
                heapq.heappush(pq, (d + w, v))

    parent = list(range(N + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    # 一条边把两个“最近加油站”连起来的最短油量需求是 dist[u] + d + dist[v]
    for u, v, d in roads:
        if near[u] and near[v] and dist[u] + d + dist[v] <= L:
            parent[find(near[u])] = find(near[v])
    home = find(1)
    return sum(1 for v in range(1, N + 1)
               if near[v] and find(near[v]) == home and 2 * dist[v] <= L)


def _brute(N, L, g, roads):
    # 状态 (点, 剩余油量) 上 BFS，油量为整数且很小
    adj = [[] for _ in range(N + 1)]
    for u, v, d in roads:
        adj[u].append((v, d)); adj[v].append((u, d))
    def reach(src_fuel_states):
        seen = set(src_fuel_states)
        st = list(seen)
        while st:
            u, f = st.pop()
            if g[u - 1]:
                f = L
            for v, d in adj[u]:
                if f >= d:
                    s = (v, f - d)
                    if s not in seen:
                        seen.add(s); st.append(s)
        return seen
    fwd = reach([(1, L)])
    ok = 0
    for v in range(1, N + 1):
        fuels = [f for (x, f) in fwd if x == v]
        if any(1 in {x for x, _ in reach([(v, f)])} for f in fuels):
            ok += 1
    return ok


if __name__ == "__main__":
    import random
    # 直线 1-2-3，只有 1 有加油站，L=4：2 号距离 2 可往返，3 号距离 5 不行
    assert compute_number_of_locations(3, 2, 4, [1, 0, 0], [[1, 2, 2], [2, 3, 3]]) == 2
    for _ in range(300):
        N = random.randint(1, 7)
        roads = []
        for v in range(2, N + 1):
            roads.append([random.randint(1, v - 1), v, random.randint(1, 4)])
        for _ in range(random.randint(0, 3)):
            if N > 1:
                a, b = random.sample(range(1, N + 1), 2)
                roads.append([a, b, random.randint(1, 4)])
        g = [1] + [random.randint(0, 1) for _ in range(N - 1)]
        L = random.randint(1, 8)
        assert compute_number_of_locations(N, len(roads), L, g, roads) == _brute(N, L, g, roads), (N, L, g, roads)
    print("ok")
